{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Male or female ≥12 years old at time of the screening visit.",
      "quote": "Male or female ≥12 years old at time of the screening visit.",
      "thresholds": [
        {
          "test": "age",
          "op": ">=",
          "value": 12,
          "unit": "years"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Patients with chronic hand and foot dermatitis diagnosed at least 3 years prior to the screening visit for patients ≥18 years old, and at least 1 year prior to the screening visit for patients ≥12 to <18 years old.",
      "quote": "Patients with chronic hand and foot dermatitis diagnosed at least 3 years prior to the screening visit for patients ≥18 years old, and at least 1 year prior to the screening visit for patients ≥12 to <18 years old.",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Patients with involvement of at least 2 anatomical areas at screening and baseline. These 2 anatomical areas could be both hands, 1 hand and 1 foot, or both feet.",
      "quote": "Patients with involvement of at least 2 anatomical areas at screening and baseline.",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Patients need to have an IGA hand and foot score of 3 or 4 (moderate-to-severe disease) at screening and baseline.",
      "quote": "Patients need to have an IGA hand and foot score of 3 or 4 (moderate-to-severe disease) at screening and baseline.",
      "thresholds": [
        {
          "test": "IGA hand and foot score",
          "op": ">=",
          "value": 3,
          "unit": null
        },
        {
          "test": "IGA hand and foot score",
          "op": "<=",
          "value": 4,
          "unit": null
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Patients with documented recent history (within 6 months before the screening visit) of inadequate response of atopic hand and foot dermatitis to topical medication(s) or for whom topical treatments of atopic hand and foot dermatitis is medically inadvisable (eg, intolerance, because of important side effects or safety risks).",
      "quote": "Patients with documented recent history (within 6 months before the screening visit) of inadequate response of atopic hand and foot dermatitis to topical medication(s) or for whom topical treatments of atopic hand and foot dermatitis is medically inadvisable (eg, intolerance, because of important side effects or safety risks).",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Patients need to meet the Hanifin and Rajka criteria for diagnosis (Hanifin, 1980).",
      "quote": "Patients need to meet the Hanifin and Rajka criteria for diagnosis (Hanifin, 1980).",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Baseline hand and foot peak Pruritus NRS score for maximum itch intensity ≥4.",
      "quote": "Baseline hand and foot peak Pruritus NRS score for maximum itch intensity ≥4.",
      "thresholds": [
        {
          "test": "Pruritus NRS",
          "op": ">=",
          "value": 4,
          "unit": null
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "At least 11 (of a total of 14*) applications of a topical emollient (moisturizer) during the 7 consecutive days immediately before the baseline visit (not including the day of randomization).",
      "quote": "At least 11 (of a total of 14*) applications of a topical emollient (moisturizer) during the 7 consecutive days immediately before the baseline visit (not including the day of randomization).",
      "thresholds": [
        {
          "test": "emollient applications",
          "op": ">=",
          "value": 11,
          "unit": "applications"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Willing and able to comply with clinic visits and study-related procedures.",
      "quote": "Willing and able to comply with clinic visits and study-related procedures.",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Provide informed consent/assent signed by study patient or legally acceptable representative.",
      "quote": "Provide informed consent/assent signed by study patient or legally acceptable representative.",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Able to understand and complete study-related questionnaires.",
      "quote": "Able to understand and complete study-related questionnaires.",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Patients need to have been compliant with the skin protection measures (as outlined in Section 8.10.3) through the entire duration of the screening period (minimum of 4 weeks but lasting to a maximum of 8 weeks). This includes avoidance of known irritants that are identified as causing exacerbation of one’s hand and foot AD.",
      "quote": "Patients need to have been compliant with the skin protection measures (as outlined in Section 8.10.3) through the entire duration of the screening period (minimum of 4 weeks but lasting to a maximum of 8 weeks).",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with a positive patch test reaction to one or more allergens (a score of 1+ or above according to International Contact Dermatitis Research Group [ICDRG] grading scale) in either the baseline patch test series OR extended baseline or supplemental patch test allergens if such additional testing is conducted by the investigator OR Personal products if testing with such products is conducted by the investigator AND Which is deemed to be clinically relevant in the view of the investigator as the current cause of the hand and foot dermatitis.",
      "quote": "Patients with a positive patch test reaction to one or more allergens (a score of 1+ or above according to International Contact Dermatitis Research Group [ICDRG] grading scale) in either the baseline patch test series OR extended baseline or supplemental patch test allergens if such additional testing is conducted by the investigator OR Personal products if testing with such products is conducted by the investigator AND Which is deemed to be clinically relevant in the view of the investigator as the current cause of the hand and foot dermatitis.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with a documented diagnosis of protein contact dermatitis of hands and/or feet. These are patients with occupational or non-occupational contact to proteins such as food, latex etc. with positive prick test who present with lesions of contact urticaria or dermatitis on hands/feet.",
      "quote": "Patients with a documented diagnosis of protein contact dermatitis of hands and/or feet.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients in whom patch testing cannot be conducted due to any reason (these include but are not limited to refusal of patient to have patch testing, inability to take patient off systemic immunosuppressants/topical AD medications for the required washout period prior to patch testing, lack of clear skin (free of lesions) on upper back and /or upper arm on which to apply patch tests, etc).",
      "quote": "Patients in whom patch testing cannot be conducted due to any reason (these include but are not limited to refusal of patient to have patch testing, inability to take patient off systemic immunosuppressants/topical AD medications for the required washout period prior to patch testing, lack of clear skin (free of lesions) on upper back and /or upper arm on which to apply patch tests, etc).",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with documented exposure to irritants in the occupational or non-occupational (household/recreational) setting that is believed to be a predominant cause of the current hand and foot dermatitis as per the judgment of the investigator.",
      "quote": "Patients with documented exposure to irritants in the occupational or non-occupational (household/recreational) setting that is believed to be a predominant cause of the current hand and foot dermatitis as per the judgment of the investigator.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Treatment with dupilumab in the past.",
      "quote": "Treatment with dupilumab in the past.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients who have used any the following treatments within 4 weeks before the baseline visit: a. Systemic corticosteroids, b. Immunosuppressive/immunomodulating drugs (eg, alitretinoin, cyclosporine, mycophenolate mofetil, IFN-γ, systemic Janus kinase inhibitors, azathioprine or methotrexate), c. Phototherapy (including localized psoralen and UVA [PUVA] or narrow band ultraviolet B [UVB] on hands and/or feet).",
      "quote": "Patients who have used any the following treatments within 4 weeks before the baseline visit: a. Systemic corticosteroids, b. Immunosuppressive/immunomodulating drugs (eg, alitretinoin, cyclosporine, mycophenolate mofetil, IFN-γ, systemic Janus kinase inhibitors, azathioprine or methotrexate), c. Phototherapy (including localized psoralen and UVA [PUVA] or narrow band ultraviolet B [UVB] on hands and/or feet).",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Treatment with biologics, other than dupilumab, as follows: a. Any cell-depleting agents including but not limited to rituximab: within 6 months before the baseline visit, or until lymphocyte and CD 19+ lymphocyte count returns to normal, whichever is longer; b. Other biologics: within 5 half-lives (if known) or 16 weeks prior to the baseline visit, whichever is longer.",
      "quote": "Treatment with biologics, other than dupilumab, as follows: a. Any cell-depleting agents including but not limited to rituximab: within 6 months before the baseline visit, or until lymphocyte and CD 19+ lymphocyte count returns to normal, whichever is longer; b. Other biologics: within 5 half-lives (if known) or 16 weeks prior to the baseline visit, whichever is longer.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Treatment with TCS or TCI or crisaborole or topical Janus kinase (JAK) inhibitor within 2 weeks before the baseline visit on the hand and foot.",
      "quote": "Treatment with TCS or TCI or crisaborole or topical Janus kinase (JAK) inhibitor within 2 weeks before the baseline visit on the hand and foot.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Treatment with an investigational drug within 8 weeks or within 5 half-lives (if known), whichever is longer, before the baseline visit.",
      "quote": "Treatment with an investigational drug within 8 weeks or within 5 half-lives (if known), whichever is longer, before the baseline visit.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Treatment with a live (attenuated) vaccine within 4 weeks before the baseline visit.",
      "quote": "Treatment with a live (attenuated) vaccine within 4 weeks before the baseline visit.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Planned or anticipated use of any prohibited medications and procedures during study treatment.",
      "quote": "Planned or anticipated use of any prohibited medications and procedures during study treatment.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Known or suspected immunodeficiency, including history of invasive opportunistic infections (eg, tuberculosis [TB], histoplasmosis, listeriosis, coccidioidomycosis, pneumocystosis, aspergillosis) despite infection resolution, or otherwise recurrent infections of abnormal frequency as judged by the investigator.",
      "quote": "Known or suspected immunodeficiency, including history of invasive opportunistic infections (eg, tuberculosis [TB], histoplasmosis, listeriosis, coccidioidomycosis, pneumocystosis, aspergillosis) despite infection resolution, or otherwise recurrent infections of abnormal frequency as judged by the investigator.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Known history of human immunodeficiency virus (HIV) infection or HIV seropositivity.",
      "quote": "Known history of human immunodeficiency virus (HIV) infection or HIV seropositivity.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "With a current diagnosis of hepatitis B viral infection at the time of screening as evidenced by: a. Positive hepatitis B surface antigen (HBsAg) or b. Positive total hepatitis B core antibody (HBcAb) confirmed by positive HBV DNA.",
      "quote": "With a current diagnosis of hepatitis B viral infection at the time of screening as evidenced by: a. Positive hepatitis B surface antigen (HBsAg) or b. Positive total hepatitis B core antibody (HBcAb) confirmed by positive HBV DNA.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "With a current diagnosis of hepatitis C viral infection at the time of screening as evidence by: a. Positive HCV Ab AND b. Positive HCV RNA.",
      "quote": "With a current diagnosis of hepatitis C viral infection at the time of screening as evidence by: a. Positive HCV Ab AND b. Positive HCV RNA.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "On current treatment for hepatic disease including but not limited to acute or chronic hepatitis, cirrhosis, or hepatic failure, or has evidence of liver disease as indicated by persistent (confirmed by repeated tests ≥2 weeks apart) elevated transaminases (alanine aminotransferase [ALT] and/or aspartate aminotransferase [AST]) more than 3 times the upper limit of normal (ULN) during the screening period.",
      "quote": "On current treatment for hepatic disease including but not limited to acute or chronic hepatitis, cirrhosis, or hepatic failure, or has evidence of liver disease as indicated by persistent (confirmed by repeated tests ≥2 weeks apart) elevated transaminases (alanine aminotransferase [ALT] and/or aspartate aminotransferase [AST]) more than 3 times the upper limit of normal (ULN) during the screening period.",
      "thresholds": [
        {
          "test": "ALT",
          "op": ">",
          "value": 3,
          "unit": "x ULN"
        },
        {
          "test": "AST",
          "op": ">",
          "value": 3,
          "unit": "x ULN"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Presence of any 1 or more of the following abnormalities in laboratory test results at screening: a. Platelets ≤100 × 103/μL, b. Neutrophils <1.5 × 103/μL.",
      "quote": "Presence of any 1 or more of the following abnormalities in laboratory test results at screening: a. Platelets ≤100 × 103/μL, b. Neutrophils <1.5 × 103/μL.",
      "thresholds": [
        {
          "test": "Platelets",
          "op": "<=",
          "value": 100,
          "unit": "10^3/μL"
        },
        {
          "test": "Neutrophils",
          "op": "<",
          "value": 1.5,
          "unit": "10^3/μL"
        }
      ]
    }
  ]
}
